    plugins: [
      RuntimePlugin(),
      ConfigPlugin({ envFilePath: '.env', envFileOptional: true }),
      LoggerPlugin({
        requestLogging: true,
        excludePaths: ['/live', '/ready', '/health', '/metrics'],
        transport: 'pino',
