      ResiliencePlugin(),
      TelemetryPlugin(),
      CqrsPlugin({ commandHandlers: COMMAND_HANDLERS, queryHandlers: QUERY_HANDLERS }),
      EventsPlugin({ handlers: EVENT_HANDLERS }),
