import type { IRouterApi, IServiceRegistry } from '@setu-ts/common';

import { describeGreeting } from '../services/greeting.service.ts';

/**
 * Registers the greeting routes: a function controller.
 *
 * @param router - The application router
 */
export function registerGreetingRoutes(router: IRouterApi, services?: IServiceRegistry): void {
  void services;
  router.group('/greetings', (routes) => {
    routes.get('/', (ctx) => ctx.response.json({ message: describeGreeting() }));
    routes.get('/:name', (ctx) =>
      ctx.response.json({ message: describeGreeting(ctx.params.name) }),
    );
  });
}

